#include "tr2/application/persistent_identity.h"
typedef struct {uint8_t bytes[262144];unsigned writes,cut;size_t tear;bool read_fail,registry_fail,prefix_fail;} Physical;
static Tr2Result rd(void *ctx,uint32_t o,void *b,size_t n){Physical*p=ctx;if(p->read_fail||o>sizeof(p->bytes)||n>sizeof(p->bytes)-o)return TR2_ERROR_STORAGE;memcpy(b,p->bytes+o,n);return TR2_OK;}
static Tr2Result wr(void *ctx,uint32_t o,const void *b,size_t n){Physical*p=ctx;assert(o<=sizeof(p->bytes)&&n<=sizeof(p->bytes)-o);p->writes++;if(p->writes==p->cut){size_t k=p->tear<n?p->tear:n;memcpy(p->bytes+o,b,k);return TR2_ERROR_STORAGE;}memcpy(p->bytes+o,b,n);return TR2_OK;}
static Tr2Result registry(void *ctx,const uint32_t uid[3],uint32_t id){Physical*p=ctx;if(uid[2]!=0xFEDCBA98u||id!=0x76543210u)return TR2_ERROR_INVALID_STATE;return p->registry_fail?TR2_ERROR_NOT_AVAILABLE:TR2_OK;}
static Tr2Result prefix(void *ctx,const uint8_t *b,size_t n){Physical*p=ctx;assert(n==51818u);(void)b;return p->prefix_fail?TR2_ERROR_CORRUPTED:TR2_OK;}
static void init(Physical*p,TransactionalImageMedia*m,uint8_t*c,bool v2){TransactionalImagePhysicalStorage s={p,rd,wr};TransactionalImageGeometry g=transactional_image_geometry_qualification_profile();assert((v2?transactional_image_media_init_v2(m,&s,&g,c,51914u):transactional_image_media_init(m,&s,&g,c,51914u))==TR2_OK);}
static PersistentIdentityRecord fixture(void){PersistentIdentityRecord r={0};r.generation=0x100000002ull;r.identity.hardware_uid[0]=0x12345678u;r.identity.hardware_uid[1]=0xABCDEF01u;r.identity.hardware_uid[2]=0xFEDCBA98u;r.identity.functional.device_id=0x76543210u;r.identity.functional.generation=3;r.identity.functional.hardware_version=2;r.identity.functional.firmware_version_major=3;r.identity.functional.firmware_version_minor=4;r.identity.functional.firmware_version_patch=5;r.identity.functional.protocol_version=7;r.identity.functional.device_capabilities=15;r.identity.unit_id=23;memcpy(r.identity.functional.serial_number,"HOST-ONLY",9);memcpy(r.identity.functional.manufacturer,"TEST",4);return r;}
static PersistentIdentityProvisioningRequest request(Physical*p,uint8_t*image,uint64_t gen){PersistentIdentityRecord r=fixture();PersistentIdentityProvisioningRequest q={0};q.context=p;q.attribution=registry;q.validate_prefix=prefix;memcpy(q.target_uid,r.identity.hardware_uid,12);q.supported_protocol_version=7;q.expected_generation=gen;q.exclusive_ownership=true;q.image=image;q.image_size=51914;assert(persistent_identity_encode(&r,image+51818)==TR2_OK);return q;}
static void repair_crc(uint8_t b[96]){uint32_t c=UINT32_MAX;unsigned i,k;for(i=0;i<92;i++){c^=b[i];for(k=0;k<8;k++)c=(c&1u)?(c>>1)^0xEDB88320u:c>>1;}c^=UINT32_MAX;b[92]=(uint8_t)(c>>24);b[93]=(uint8_t)(c>>16);b[94]=(uint8_t)(c>>8);b[95]=(uint8_t)c;}
static void codec(void){uint8_t b[96],copy[96];PersistentIdentityRecord r=fixture(),out;ModbusBlock0Image b0;unsigned i;assert(persistent_identity_encode(&r,b)==TR2_OK);assert(memcmp(b,"TR2D\0\1\0\x60",8)==0);assert(b[8]==0&&b[11]==1&&b[15]==2);assert(b[28]==0x76&&b[31]==0x10);assert(b[92]==0x0c&&b[93]==0x19&&b[94]==0x00&&b[95]==0x38);assert(persistent_identity_decode(b,96,&out)==TR2_OK);assert(out.generation==r.generation);assert(modbus_project_b0(&out.identity.functional,&b0)==TR2_OK);assert(b0.registers[0]==0x7654&&b0.registers[1]==0x3210&&b0.registers[20]==0);assert(memcmp(out.identity.hardware_uid,r.identity.hardware_uid,12)==0);for(i=0;i<96;i++){memcpy(copy,b,96);copy[i]^=1;assert(persistent_identity_decode(copy,96,&out)!=TR2_OK);}memcpy(copy,b,96);copy[5]=2;repair_crc(copy);assert(persistent_identity_decode(copy,96,&out)==TR2_ERROR_UNSUPPORTED);
memcpy(copy,b,96);copy[73]=1;repair_crc(copy);assert(persistent_identity_decode(copy,96,&out)==TR2_ERROR_CORRUPTED);
memcpy(copy,b,96);copy[72]=0;repair_crc(copy);assert(persistent_identity_decode(copy,96,&out)==TR2_ERROR_CORRUPTED);
memcpy(copy,b,96);copy[46]=0x80;repair_crc(copy);assert(persistent_identity_decode(copy,96,&out)==TR2_ERROR_CORRUPTED);
memcpy(copy,b,96);memset(copy+8,0,8);repair_crc(copy);assert(persistent_identity_decode(copy,96,&out)==TR2_ERROR_CORRUPTED);
r.identity.unit_id=248;assert(persistent_identity_encode(&r,b)==TR2_ERROR_INVALID_ARGUMENT);r=fixture();r.identity.functional.serial_number[0]=(char)128;assert(persistent_identity_encode(&r,b)==TR2_ERROR_INVALID_ARGUMENT);r=fixture();r.generation=0;assert(persistent_identity_encode(&r,b)==TR2_ERROR_INVALID_ARGUMENT);}
static void transitions(bool migration,unsigned cut,size_t tear){Physical*p=calloc(1,sizeof(*p));uint8_t*c=malloc(51914),*image=calloc(1,51914),*again=malloc(51914);TransactionalImageMedia m,reboot,old;TransactionalImageRecoveryResult rec;ProductionProvisioningResult result;PersistentIdentityProvisioningRequest q;unsigned i;assert(p&&c&&image&&again);memset(p->bytes,0xFF,sizeof(p->bytes));init(p,&m,c,true);if(migration){assert(transactional_image_media_format_empty(&m)==TR2_OK);for(i=0;i<51818;i++)image[i]=(uint8_t)(i*17u+3u);assert(m.interface.write(&m,0,image,51818)==TR2_OK);assert(m.interface.commit(&m)==TR2_OK);}q=request(p,image,migration?2:0);p->writes=0;p->cut=cut;p->tear=tear;
 if(cut){assert(persistent_identity_provision(&m,&q,true,&result)==TR2_ERROR_STORAGE);assert(!result.identity_available&&result.write_attempted);}else{assert(persistent_identity_provision(&m,&q,true,&result)==TR2_OK);assert(result.identity_available&&p->writes==3);q.expected_generation=migration?3:1;assert(persistent_identity_provision(&m,&q,true,&result)==TR2_OK&&result.unchanged&&p->writes==3);q.expected_generation=0;assert(persistent_identity_provision(&m,&q,true,&result)==TR2_ERROR_INVALID_STATE);}
 p->cut=0;init(p,&reboot,again,true);assert(transactional_image_media_recover(&reboot,&rec)==TR2_OK);
 if(!cut||(cut==3&&tear>=64)){assert(rec.status==TRANSACTIONAL_IMAGE_RECOVERY_VALID&&reboot.logical_version==2&&memcmp(again,image,51914)==0);init(p,&old,c,false);assert(transactional_image_media_recover(&old,&rec)==TR2_OK&&rec.status==TRANSACTIONAL_IMAGE_RECOVERY_UNSUPPORTED);}else if(migration){assert(rec.status==TRANSACTIONAL_IMAGE_RECOVERY_VALID&&reboot.logical_version==1&&memcmp(again,image,51818)==0);}else{assert(rec.status!=TRANSACTIONAL_IMAGE_RECOVERY_VALID);}
 free(again);free(image);free(c);free(p);}
static void guards(void){Physical*p=calloc(1,sizeof(*p));uint8_t*c=malloc(51914),*image=calloc(1,51914);TransactionalImageMedia m;ProductionProvisioningResult out;PersistentIdentityProvisioningRequest q;TransactionalImageRecoveryResult rec;assert(p&&c&&image);memset(p->bytes,0xFF,sizeof(p->bytes));init(p,&m,c,true);q=request(p,image,0);assert(persistent_identity_provision(&m,&q,false,&out)==TR2_ERROR_NOT_AVAILABLE);q.exclusive_ownership=false;assert(persistent_identity_provision(&m,&q,true,&out)==TR2_ERROR_NOT_AVAILABLE);q.exclusive_ownership=true;q.target_uid[2]^=1;assert(persistent_identity_provision(&m,&q,true,&out)==TR2_ERROR_INVALID_STATE);q.target_uid[2]^=1;q.supported_protocol_version=8;assert(persistent_identity_provision(&m,&q,true,&out)==TR2_ERROR_UNSUPPORTED);q.supported_protocol_version=7;p->registry_fail=true;assert(persistent_identity_provision(&m,&q,true,&out)==TR2_ERROR_NOT_AVAILABLE);p->registry_fail=false;p->prefix_fail=true;assert(persistent_identity_provision(&m,&q,true,&out)==TR2_ERROR_CORRUPTED);p->prefix_fail=false;q.attribution=NULL;assert(persistent_identity_provision(&m,&q,true,&out)==TR2_ERROR_NOT_AVAILABLE);q.attribution=registry;q.image=c;assert(persistent_identity_provision(&m,&q,true,&out)==TR2_ERROR_INVALID_ARGUMENT);q.image=image;assert(p->writes==0);assert(persistent_identity_provision(&m,&q,true,&out)==TR2_OK);q.expected_generation=1;image[100]^=1;assert(persistent_identity_provision(&m,&q,true,&out)==TR2_ERROR_INVALID_STATE);image[100]^=1;image[51818+28]^=1;assert(persistent_identity_provision(&m,&q,true,&out)==TR2_ERROR_CORRUPTED);assert(p->writes==3);p->read_fail=true;assert(transactional_image_media_recover(&m,&rec)==TR2_OK&&rec.status==TRANSACTIONAL_IMAGE_RECOVERY_UNAVAILABLE);assert(!m.recovered&&m.interface.commit(&m)==TR2_ERROR_INVALID_STATE);free(image);free(c);free(p);}
static void prefix_and_runtime_commit(void){
 Physical *p=calloc(1,sizeof(*p));uint8_t*c=malloc(51914),*image=calloc(1,51914);TransactionalImageMedia m;ProductionProvisioningResult out;PersistentIdentityProvisioningRequest q;TransactionalImageRecoveryResult rec;PersistentIdentityRecord id;ModbusBlock0Image b0;uint8_t byte=0xAB;
 assert(p&&c&&image);memset(p->bytes,0xFF,sizeof(p->bytes));init(p,&m,c,true);assert(transactional_image_media_format_empty(&m)==TR2_OK);q=request(p,image,1);p->writes=0;image[51802]=1;assert(persistent_identity_provision(&m,&q,true,&out)==TR2_ERROR_INVALID_STATE&&p->writes==0);image[51802]=0;assert(persistent_identity_provision(&m,&q,true,&out)==TR2_OK);assert(m.interface.write(&m,100,&byte,1)==TR2_OK);assert(m.interface.commit(&m)==TR2_OK);assert(transactional_image_media_recover(&m,&rec)==TR2_OK&&rec.generation==3&&m.logical_version==2&&c[100]==0xAB);assert(persistent_identity_from_image(c,51914,q.target_uid,7,&id,&b0)==TR2_OK&&id.generation==0x100000002ull);
 {TransactionalImagePhysicalStorage physical={p,rd,wr};TransactionalImageGeometry g=transactional_image_geometry_qualification_profile();g.image_area_size=64+51818;assert(transactional_image_media_init_v2(&m,&physical,&g,c,51914)==TR2_ERROR_INVALID_ARGUMENT);}
 free(image);free(c);free(p);
}
static void attribution(void){
 PersistentIdentityRecord r=fixture();PersistentIdentityAssignment entries[2]={0};
 memcpy(entries[0].hardware_uid,r.identity.hardware_uid,12);entries[0].device_id=r.identity.functional.device_id;
 entries[1].hardware_uid[0]=77;entries[1].device_id=123;
 assert(persistent_identity_attribution_check(NULL,0,r.identity.hardware_uid,entries[0].device_id)==TR2_ERROR_NOT_AVAILABLE);
 assert(persistent_identity_attribution_check(entries,2,r.identity.hardware_uid,entries[0].device_id)==TR2_OK);
 assert(persistent_identity_attribution_check(entries,2,r.identity.hardware_uid,7)==TR2_ERROR_INVALID_STATE);
 entries[1].device_id=entries[0].device_id;assert(persistent_identity_attribution_check(entries,2,r.identity.hardware_uid,entries[0].device_id)==TR2_ERROR_INVALID_STATE);
 entries[1].device_id=123;memcpy(entries[1].hardware_uid,entries[0].hardware_uid,12);assert(persistent_identity_attribution_check(entries,2,r.identity.hardware_uid,entries[0].device_id)==TR2_ERROR_INVALID_STATE);
 entries[1].hardware_uid[2]^=1;assert(persistent_identity_attribution_check(entries,2,entries[1].hardware_uid,123)==TR2_OK);
}
int main(void){unsigned phase,k;const size_t tears[]={0,1,31,63,64,25957,51914};codec();guards();attribution();prefix_and_runtime_commit();transitions(false,0,0);transitions(true,0,0);for(phase=1;phase<=3;phase++)for(k=0;k<sizeof(tears)/sizeof(tears[0]);k++){transitions(false,phase,tears[k]);transitions(true,phase,tears[k]);}return 0;}
